/**
 * Product captures in `static/screens/`, generated by `scripts/build-screens.py`.
 * Keep names and widths in sync with that script's `SCREENS` list.
 * Each capture has `<name>-<w>.webp` for every width and `<name>-<max>.jpg` as fallback.
 */
export type Shot = {
  name: string;
  /** Output widths, ascending. */
  widths: number[];
  /** Intrinsic aspect, used for width/height attributes (no layout shift). */
  aspect: [number, number];
  alt: string;
};

const TV: [number, number] = [16, 9];
const PHONE: [number, number] = [1, 2];

export const SHOTS = {
  heroTv: {
    name: 'tv-appletv-preplay',
    widths: [480, 720, 960, 1440],
    aspect: TV,
    alt: 'PlayBridge on Apple TV: Big Buck Bunny (2008, 8 min) ready to play, with a “Playing in 4s” countdown.'
  },
  heroPhone: {
    name: 'phone-remote-context',
    widths: [240, 480],
    aspect: PHONE,
    alt: 'PlayBridge remote on Android, Context tab: Big Buck Bunny watching on Master bedroom TV, with a seek strip and −10 s, +10 s, loop and stop controls.'
  },
  browser: {
    name: 'phone-browser',
    widths: [360, 720],
    aspect: PHONE,
    alt: 'PlayBridge browser on Android with remote, screen and cast buttons in the address bar; an ad-blocker test page reports 100 out of 100 points.'
  },
  pairing: {
    name: 'tv-android-pairing',
    widths: [480, 960, 1440],
    aspect: TV,
    alt: 'PlayBridge receiver on Android TV, Pairing tab: “Ready to Connect”, the TV name and its local address, waiting for a phone to connect.'
  },
  remote: {
    name: 'phone-remote-touchpad',
    widths: [240, 480],
    aspect: PHONE,
    alt: 'PlayBridge remote on Android in Touchpad mode, with Context, D-Pad and Keyboard tabs and skip, loop and stop controls.'
  },
  resume: {
    name: 'phone-title-resume',
    widths: [360, 720],
    aspect: PHONE,
    alt: 'Big Buck Bunny details on the PlayBridge phone app: watching on Master bedroom TV with ExoPlayer, a “Resume · 0:52” button, and a now-playing bar.'
  },
  engines: {
    name: 'tv-appletv-engines',
    widths: [480, 960],
    aspect: TV,
    alt: 'PlayBridge settings on Apple TV: choose the playback engine — Native (AVPlayer), VLC Player or MPV Player.'
  }
} satisfies Record<string, Shot>;

export function webpSrcset(shot: Shot): string {
  return shot.widths.map((w) => `/screens/${shot.name}-${w}.webp ${w}w`).join(', ');
}

export function fallbackSrc(shot: Shot): string {
  return `/screens/${shot.name}-${shot.widths[shot.widths.length - 1]}.jpg`;
}

/** Width/height attributes at the largest output width. */
export function dims(shot: Shot): { width: number; height: number } {
  const width = shot.widths[shot.widths.length - 1];
  return { width, height: Math.round((width * shot.aspect[1]) / shot.aspect[0]) };
}
